content.content:
1	// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
2	// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
3	// 数据只存本机 chrome.storage.local，不上传任何服务器。
4	
5	importScripts('logger.js');
6	var log = TemuLogger.createLogger('bg');
7	
8	const GOODS_URL = 'https://agentseller.temu.com/goods/list';
9	const DEFAULT_CONFIG = { webhook: '', intervalMinutes: 15, enabled: true, storeName: '' };
10	
11	// ---------------- 解析 ----------------
12	function parseCountStatus(body) {
13	  try {
14	    const j = JSON.parse(body);
15	    const list = j && j.result && j.result.skcTopStatusCountList;
16	    if (!Array.isArray(list)) return null;
17	    const pick = (s) => {
18	      const x = list.find((e) => e && e.skcTopStatus === s);
19	      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
20	    };
21	    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
22	  } catch (e) { return null; }
23	}
24	function parsePageQuery(body) {
25	  try {
26	    const j = JSON.parse(body);
27	    const r = j && j.result;
28	    if (!r) return null;
29	    return { total: r.total };
30	  } catch (e) { return null; }
31	}
32	
33	// ---------------- 存取 ----------------
34	async function getConfig() {
35	  const { config } = await chrome.storage.local.get('config');
36	  return Object.assign({}, DEFAULT_CONFIG, config || {});
37	}
38	async function getStores() {
39	  const { stores } = await chrome.storage.local.get('stores');
40	  return stores || {};
41	}
42	async function saveStores(stores) {
43	  await chrome.storage.local.set({ stores });
44	}
45	// 更新某店的最新读数
46	async function updateStoreLatest(name, patch) {
47	  const stores = await getStores();
48	  const s = stores[name] || { latest: {}, snapshot: {} };
49	  s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
50	  stores[name] = s;
51	  await saveStores(stores);
52	  return s;
53	}
54	
55	// ---------------- 飞书 ----------------
56	async function sendFeishu(webhook, title, lines) {
57	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
58	  const card = {
59	    msg_type: 'interactive',
60	    card: {
61	      header: { title: { tag: 'plain_text', content: title }, template: 'red' },
62	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
63	    },
64	  };
65	  try {
66	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
67	    const data = await resp.json().catch(() => ({}));
68	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
69	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
70	  } catch (e) {
71	    return { ok: false, msg: '发送失败：' + (e && e.message) };
72	  }
73	}
74	
75	// ---------------- 商品明细 → 带链接的告警行 ----------------
76	// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
77	function editLink(productId) {
78	  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
79	}
80	// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
81	function itemLines(items, total) {
82	  const lines = [];
83	  if (Array.isArray(items) && items.length) {
84	    for (const it of items) {
85	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
86	      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
87	    }
88	    if (typeof total === 'number' && total > items.length) {
89	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
90	    }
91	  } else if (typeof total === 'number' && total > 0) {
92	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
93	  }
94	  return lines;
95	}
96	
97	// 让 content.js 主动点「商品流量待关注」筛选，捞出这几条被限流的具体商品（productId+name+skc）
98	async function scanWatchViaTab() {
99	  const tab = await getGoodsTab();
100	  if (!tab) return null;
101	  return await sendTabRetry(tab.id, { cmd: 'scanWatchList' }, 3);
102	}
103	
104	// ---------------- 对比 & 告警（按店） ----------------
105	// 按店串行：同一店的多条读数消息（切店时常一秒内来两条）排队逐个处理，
106	// 避免"都读到旧快照各报一次"的竞态导致同一事件重复告警。
107	const alertChains = {};
108	function diffAndAlert(name) {
109	  const prev = alertChains[name] || Promise.resolve();
110	  const next = prev.then(() => _diffAndAlert(name)).catch(() => {});
111	  alertChains[name] = next;
112	  return next;
113	}
114	
115	async function _diffAndAlert(name) {
116	  const cfg = await getConfig();
117	  if (!cfg.enabled) return;
118	  const stores = await getStores();
119	  const s = stores[name];
120	  if (!s) return;
121	  const latest = s.latest || {};
122	  const snap = s.snapshot || {};
123	  const events = [];
124	
125	  // 在售数量下降：数字告警（被动监测第一时间发现），diffOnSale 在轮巡时带具体商品名+链接点名。
126	  // v3 曾移除此项（担心与 diffOnSale 重复），但 diffOnSale 只在空闲轮巡触发，移除后用户手动刷新/页面
127	  // 自然浏览时下架完全漏报——现在恢复，与 diffOnSale 互补：此处报数字，轮巡补点名。
128	  if (typeof latest.onSale === 'number' && typeof snap.onSale === 'number' && latest.onSale < snap.onSale) {
129	    events.push(`📉 在售数量下降：${snap.onSale} → ${latest.onSale}`);
130	  }
131	  if (typeof latest.trafficWatch === 'number' && typeof snap.trafficWatch === 'number' && latest.trafficWatch > snap.trafficWatch) {
132	    events.push(`⚠️ 商品流量待关注增加：${snap.trafficWatch} → ${latest.trafficWatch}`);
133	    // 被动扫到的 watchItems 往往为空（限流商品散落在其它页）→ 主动点筛选把这几条捞出来，带链接点名。
134	    let items = Array.isArray(latest.watchItems) ? latest.watchItems : [];
135	    let total = latest.trafficWatch;
136	    const scan = await scanWatchViaTab();
137	    if (scan && scan.applied && Array.isArray(scan.items) && scan.items.length) {
138	      items = scan.items;
139	      if (typeof scan.total === 'number') total = scan.total;
140	    }
141	    events.push(...itemLines(items, total));
142	  }
143	  // 「商品流量近期有下降」商品数增加（相对已建立的基准，首次不报）
144	  if (typeof latest.trafficDecline === 'number' && typeof snap.trafficDecline === 'number' && latest.trafficDecline > snap.trafficDecline) {
145	    events.push(`🔴 商品流量近期有下降增加：${snap.trafficDecline} → ${latest.trafficDecline}（本页可见）`);
146	    events.push(...itemLines(latest.declineItems, null));
147	  }
148	
149	  if (events.length > 0) {
150	    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
151	    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
152	    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
153	  }
154	
155	  // 合并式更新该店基准快照（只覆盖本次拿到的数值），幂等只报一次。
156	  // 重新取一次 store：主动扫筛选期间 content 可能又上报过 latest，避免用旧闭包覆盖。
157	  const stores2 = await getStores();
158	  const s2 = stores2[name] || s;
159	  const L2 = s2.latest || latest;
160	  const newSnap = Object.assign({}, s2.snapshot || snap);
161	  if (typeof L2.onSale === 'number') newSnap.onSale = L2.onSale;
162	  if (typeof L2.total === 'number') newSnap.total = L2.total;
163	  if (typeof L2.trafficWatch === 'number') newSnap.trafficWatch = L2.trafficWatch;
164	  if (typeof L2.trafficDecline === 'number') newSnap.trafficDecline = L2.trafficDecline;
165	  newSnap.ts = Date.now();
166	  s2.snapshot = newSnap;
167	  stores2[name] = s2;
168	  await saveStores(stores2);
169	}
170	
171	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
172	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
173	async function diffOnSale(name, items, onSaleTabCount) {
174	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
175	  const cfg = await getConfig();
176	  const stores = await getStores();
177	  const s = stores[name] || { latest: {}, snapshot: {} };
178	  // 防残缺扫描/筛选污染误判：以"扫描当时在干净视图下读到的「在售中 N」"为权威在售数
179	  // （content.js scanOnSaleList 复位后读的，不会被「商品流量待关注」筛选污染）；
180	  // 读不到才回退 countStatus 的 latest.onSale。扫到的商品数必须不少于它，否则视为没扫全 → 跳过。
181	  const known = (typeof onSaleTabCount === 'number' && onSaleTabCount > 0)
182	    ? onSaleTabCount
183	    : (s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null);
184	  if (known != null && items.length < known) return 0;
185	  const newMap = {};
186	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
187	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
188	  let delistedCount = 0;
189	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
190	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
191	    delistedCount = delisted.length;
192	    if (delisted.length) {
193	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
194	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}）:`,
195	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
196	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
197	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
198	    }
199	  }
200	  // 重新取一次 stores 再写：_diffAndAlert 可能在 diffOnSale 处理期间并发更新过 snapshot 的
201	  // 数值字段（onSale/trafficWatch 等），直接用初始读到的 s 会覆盖掉这些更新 → 基准腐败 → "数据后来不准"。
202	  const stores2 = await getStores();
203	  const s2 = stores2[name] || s;
204	  s2.snapshot = Object.assign({}, s2.snapshot || s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
205	  stores2[name] = s2;
206	  await saveStores(stores2);
207	  return delistedCount;
208	}
209	
210	// 解析店铺名：优先用页面读到的店名；读不到则退回配置里手填的，再退回“当前店铺”
211	async function resolveStore(msgStore) {
212	  if (msgStore && String(msgStore).trim()) return String(msgStore).trim();
213	  const cfg = await getConfig();
214	  return (cfg.storeName && cfg.storeName.trim()) || '当前店铺';
215	}
216	
217	// ---------------- 消息处理 ----------------
218	chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
219	  (async () => {
220	    try {
221	    if (msg.type === 'log') {
222	      if (msg.entry && msg.entry.ts && msg.entry.level) {
223	        TemuLogger._writeEntry(msg.entry);
224	      }
225	      sendResponse({ ok: true });
226	      return;
227	    }
228	    if (msg.type === 'capture') {
229	      const name = await resolveStore(msg.store);
230	      if (msg.kind === 'countStatus') {
231	        const p = parseCountStatus(msg.body);
232	        if (p && p.onSale != null) {
233	          await updateStoreLatest(name, { onSale: p.onSale, unpublished: p.unpublished, removed: p.removed, deleted: p.deleted });
234	          await diffAndAlert(name);
235	        }
236	      } else if (msg.kind === 'pageQuery') {
237	        const p = parsePageQuery(msg.body);
238	        if (p) await updateStoreLatest(name, { total: p.total });
239	      }
240	      sendResponse({ ok: true });
241	      return;
242	    }
243	    if (msg.type === 'chipStats') {
244	      const patch = {};
245	      if (typeof msg.trafficWatch === 'number') patch.trafficWatch = msg.trafficWatch;
246	      if (typeof msg.trafficDecline === 'number') patch.trafficDecline = msg.trafficDecline;
247	      if (Array.isArray(msg.watchItems)) patch.watchItems = msg.watchItems;
248	      if (Array.isArray(msg.declineItems)) patch.declineItems = msg.declineItems;
249	      if (Object.keys(patch).length) {
250	        const name = await resolveStore(msg.store);
251	        await updateStoreLatest(name, patch);
252	        await diffAndAlert(name);
253	      }
254	      sendResponse({ ok: true });
255	      return;
256	    }
257	    if (msg.type === 'getStatus') {
258	      sendResponse({ bgVersion: 'v6-下架漏报修复', config: await getConfig(), stores: await getStores(), ...(await chrome.storage.local.get(['lastAlert', 'lastCycle'])) });
259	      return;
260	    }
261	    if (msg.type === 'addStore') {
262	      const name = (msg.name || '').trim();
263	      if (!name) { sendResponse({ ok: false, msg: '店铺名不能为空' }); return; }
264	      const stores = await getStores();
265	      if (stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」已存在' }); return; }
266	      stores[name] = { latest: {}, snapshot: {} };
267	      await saveStores(stores);
268	      sendResponse({ ok: true, msg: '已添加「' + name + '」，下次轮巡将尝试切到该店抓数' });
269	      return;
270	    }
271	    if (msg.type === 'deleteStore') {
272	      const name = (msg.name || '').trim();
273	      const stores = await getStores();
274	      if (!stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」不存在' }); return; }
275	      delete stores[name];
276	      await saveStores(stores);
277	      sendResponse({ ok: true, msg: '已删除「' + name + '」' });
278	      return;
279	    }
280	    if (msg.type === 'checkNow') {
281	      sendResponse(await pollNow());
282	      return;
283	    }
284	    if (msg.type === 'cycleNow') {
285	      sendResponse(await cycleStores('manual'));
286	      return;
287	    }
288	    if (msg.type === 'testFeishu') {
289	      const cfg = await getConfig();
290	      const r = await sendFeishu(cfg.webhook, '✅ Temu 监测测试', ['这是一条测试消息，收到说明飞书配置正常。', '', `_${new Date().toLocaleString('zh-CN')}_`]);
291	      sendResponse(r);
292	      return;
293	    }
294	    } catch (e) {
295	      log.error('Message handler error: ' + (e && e.message ? e.message : String(e)));
296	      sendResponse({ ok: false, msg: 'Internal error' });
297	    }
298	  })();
299	  return true;
300	});
301	
302	// ---------------- 自动轮巡（切遍每个店抓数，再切回原店；仅空闲时触发） ----------------
303	const IDLE_SECONDS = 240; // 无操作 4 分钟视为空闲
304	let cycling = false;
305	
306	async function getGoodsTab() {
307	  const tabs = await chrome.tabs.query({ url: 'https://agentseller.temu.com/*' });
308	  return tabs.find((t) => /goods\/list/.test(t.url || '')) || tabs[0] || null;
309	}
310	function sendTab(tabId, cmd) {
311	  return new Promise((resolve) => {
312	    try {
313	      chrome.tabs.sendMessage(tabId, cmd, (resp) => {
314	        if (chrome.runtime.lastError) resolve(null); else resolve(resp);
315	      });
316	    } catch (e) { resolve(null); }
317	  });
318	}
319	async function sendTabRetry(tabId, cmd, tries) {
320	  for (let i = 0; i < (tries || 8); i++) {
321	    const r = await sendTab(tabId, cmd);
322	    if (r) return r;
323	    await new Promise((res) => setTimeout(res, 1000)); // 页面重载后 content 未就绪，重试
324	  }
325	  return null;
326	}
327	function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
328	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
329	async function waitForStoreCapture(name, sinceTs, timeout) {
330	  const t0 = Date.now();
331	  while (Date.now() - t0 < (timeout || 25000)) {
332	    const stores = await getStores();
333	    const L = stores[name] && stores[name].latest;
334	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
335	    await sleep(1500);
336	  }
337	  return false;
338	}
339	
340	async function cycleStores(reason) {
341	  if (cycling) return { ok: false, msg: '轮巡进行中' };
342	  cycling = true;
343	  const cycleLog = [];
344	  try {
345	    const tab = await getGoodsTab();
346	    if (!tab) return { ok: false, msg: '没有打开的 Temu 商品页' };
347	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
348	    const original = cur && cur.store;
349	    cycleLog.push('当前店：' + (original || '未知'));
350	
351	    // 店铺清单：优先用”已知店”（之前逛各店时按顶栏店名记下的，干净准确）；
352	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
353	    const known = Object.keys(await getStores()).filter((n) => n && n !== '当前店铺');
354	    let names;
355	    if (known.length >= 2) {
356	      names = known;
357	      cycleLog.push('店铺(已知)：' + names.join(', '));
358	    } else {
359	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
360	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
361	      cycleLog.push('店铺(探测)：' + names.join(', '));
362	    }
363	    if (names.length === 0) return { ok: false, msg: '没识别到店铺清单' };
364	
365	    for (const name of names) {
366	      if (name === original) continue; // 原店最后再确认；先切别的
367	      const since = Date.now();
368	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
369	      if (!r || !r.ok) { cycleLog.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
370	      const got = await waitForStoreCapture(name, since, 25000);
371	      cycleLog.push((got ? '✓ ' : '✗ ') + name);
372	      // 扫在售清单 → diff 出下架商品（带链接告警）
373	      if (got) {
374	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
375	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items, os.onSaleTabCount); if (d) cycleLog.push('  ↳下架' + d + '个'); }
376	      }
377	    }
378	    // 切回原店
379	    if (original) {
380	      const since = Date.now();
381	      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
382	      const gotBack = await waitForStoreCapture(original, since, 25000);
383	      if (gotBack) {
384	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
385	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items, os.onSaleTabCount); if (d) cycleLog.push('  ↳' + original + '下架' + d + '个'); }
386	      }
387	      cycleLog.push('已切回 ' + original);
388	    }
389	    const summary = cycleLog.join(' | ');
390	    await chrome.storage.local.set({ lastCycle: { ts: Date.now(), reason, summary } });
391	    return { ok: true, msg: summary };
392	  } finally { cycling = false; }
393	}
394	
395	async function pollNow() {
396	  const tab = await getGoodsTab();
397	  if (!tab) return { ok: false, msg: '未找到打开的 Temu 后台标签页，请先登录并打开商品列表页' };
398	  if (/goods\/list/.test(tab.url || '')) { await chrome.tabs.reload(tab.id, { bypassCache: false }); return { ok: true, msg: '已刷新后台商品页' }; }
399	  await chrome.tabs.update(tab.id, { url: GOODS_URL });
400	  return { ok: true, msg: '已导航到商品列表页' };
401	}
402	
403	// 定时：空闲则轮巡所有店，否则不打扰（靠随看随记覆盖当前店）
404	chrome.alarms.onAlarm.addListener((a) => {
405	  if (a.name !== 'poll') return;
406	  chrome.idle.queryState(IDLE_SECONDS, (state) => {
407	    if (state === 'idle' || state === 'locked') cycleStores('idle');
408	  });
409	});
410	
411	async function setupAlarm() {
412	  await chrome.storage.local.remove('trafficSample'); // 清早期诊断残留
413	  const cfg = await getConfig();
414	  await chrome.alarms.clear('poll');
415	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
416	}
417	chrome.runtime.onInstalled.addListener(setupAlarm);
418	chrome.runtime.onStartup.addListener(setupAlarm);
419	chrome.storage.onChanged.addListener((changes, area) => { if (area === 'local' && changes.config) setupAlarm(); });
420

