$ErrorActionPreference = 'Stop'

$src = "E:\project\temu\temu-plugin"
$parent = Split-Path $src -Parent
$name = Split-Path $src -Leaf
$crx = Join-Path $parent ($name + '.crx')
$pem = Join-Path $parent ($name + '.pem')

# 定位 chrome.exe
$candidates = @(
  "$env:ProgramFiles\Google\Chrome\Application\chrome.exe",
  "${env:ProgramFiles(x86)}\Google\Chrome\Application\chrome.exe",
  "$env:LOCALAPPDATA\Google\Chrome\Application\chrome.exe"
)
$chrome = $candidates | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $chrome) {
  try { $chrome = (Get-Command chrome.exe -ErrorAction Stop).Source } catch {}
}
if (-not $chrome) { Write-Host '[错误] 找不到 chrome.exe' -ForegroundColor Red; exit 1 }
Write-Host ("Chrome: " + $chrome)
Write-Host ("打包源: " + $src)

# 组装参数
$args = @("--pack-extension=$src")
if (Test-Path $pem) {
  $args += "--pack-extension-key=$pem"
  Write-Host ("复用密钥: " + $pem)
} else {
  Write-Host '首次打包，将生成新密钥。'
}

# 打包
& $chrome @args
Start-Sleep -Seconds 3

if (Test-Path $crx) {
  $size = [math]::Round((Get-Item $crx).Length / 1KB, 1)
  Write-Host ''
  Write-Host ('[成功] 已生成: ' + $crx + ' (' + $size + ' KB)') -ForegroundColor Green
} else {
  Write-Host '[失败] 未生成 .crx' -ForegroundColor Red
}
